def centeredQuadraticForm {n : ℕ} (a : Fin n → Fin n → 𝕜)
    (θ : Fin n → Bool) : 𝕜 :=
  ∑ i, ∑ j, if i = j then 0 else scalarSign (θ i) * scalarSign (θ j) * a i j

